-- Objects the server needs in the control database that the pg_dump baseline
-- (002_control.sql, regenerated by regen.sh) does not contain. Kept separate
-- so regenerating 002_control.sql does not drop them. Applied to the control
-- database by docker-init.sh.

CREATE OR REPLACE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

-- RealmRepository (control-plane pool) reads and writes realm_domains.
CREATE TABLE IF NOT EXISTS public.realm_domains (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    realm_id uuid NOT NULL,
    domain character varying NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    is_verified boolean DEFAULT false NOT NULL,
    verification_token character varying,
    verification_method character varying,
    verified_at timestamp with time zone,
    ssl_enabled boolean DEFAULT true NOT NULL,
    ssl_certificate_expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT realm_domains_pkey PRIMARY KEY (id),
    CONSTRAINT realm_domains_realm_id_fkey FOREIGN KEY (realm_id)
        REFERENCES public.realms(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_realm_domains_domain ON public.realm_domains USING btree (domain);
CREATE INDEX IF NOT EXISTS idx_realm_domains_realm_id ON public.realm_domains USING btree (realm_id);
CREATE INDEX IF NOT EXISTS idx_realm_domains_verified ON public.realm_domains USING btree (is_verified) WHERE (is_verified = true);
CREATE UNIQUE INDEX IF NOT EXISTS realm_domains_domain_key ON public.realm_domains USING btree (domain);

CREATE TRIGGER update_realm_domains_updated_at BEFORE UPDATE ON public.realm_domains
    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
